CREATE TABLE T_P790_A(id INT, age INT);
CREATE VIEW V_P790_A AS SELECT id, age, id + age AS data FROM T_P790_A;
SELECT COUNT(*) FROM V_P790_A;
SELECT COUNT(id) FROM V_P790_A;
SELECT COUNT(data) FROM V_P790_A;
SELECT SUM(age) FROM V_P790_A;
SELECT COUNT(*) FROM V_P790_A WHERE id IS NULL;
SELECT COUNT(*) FROM V_P790_A WHERE id IS NOT NULL;
CREATE VIEW V_P790_SINGLE AS SELECT id, age FROM T_P790_A;
DELETE FROM V_P790_SINGLE WHERE id = 40000;
CREATE VIEW V_P790_EXPR AS SELECT id, age, id + age AS data FROM T_P790_A;
CREATE TABLE T_P790_B(id INT, score INT);
CREATE VIEW V_P790_JOIN AS SELECT a.id, a.age, b.score FROM T_P790_A a, T_P790_B b WHERE (a.id IS NOT NULL AND a.id = b.id) OR (a.id IS NULL AND b.id IS NULL);
SELECT COUNT(*) FROM V_P790_JOIN;
CREATE VIEW V_P790_AGG AS SELECT COUNT(*) AS cnt, SUM(age) AS total FROM T_P790_A;
SELECT cnt, total FROM V_P790_AGG;
SELECT COUNT(*) FROM T_P790_A;
